// ===========================================
// VOICE DATA - Kie.ai ElevenLabs v2.5 Turbo
// Supports preset names AND ElevenLabs voice IDs
// Static previews via: https://static.aiquickdraw.com/elevenlabs/voice/<id>.mp3
// ===========================================

import { ENGINE_LIMITS, type TTSEngine } from './constants'

export interface VoiceData {
    id: string           // Unique identifier (voice name lowercase, no spaces)
    name: string         // Display name shown to user
    voiceName: string    // Value sent to Kie.ai API (Gemini voice name, preset name, or ElevenLabs voice ID)
    elevenLabsId?: string // ElevenLabs voice ID for preview URLs and extended voices
    category: string     // Our custom category
    gender: 'male' | 'female' | 'neutral'
    accent: string
    language: string
    age: string
    description: string
    useCases: string[]
    previewText?: string
    tags: string[]
    previewUrl?: string  // Explicit preview URL (used for Gemini/Fish voices; served from /public)
    hidden?: boolean     // Hidden from the library UI but still resolvable by id/name (history, saved voices)
    engine?: 'gemini' | 'fish' | 'smallest'  // TTS engine serving this voice (default: gemini via Kie.ai)
    fishReferenceId?: string    // Fish Audio voice model id (engine === 'fish' only)
    smallestVoiceId?: string    // Smallest.ai voice id (engine === 'smallest' only)
}

// Our 9 categories
export const VOICE_CATEGORIES = [
    'Commentary',
    'Documentary',
    'Storytelling',
    'Short Videos',
    'Crime & Suspense',
    'Character',
    'Meditation & ASMR',
    'Announcer & Radio',
    'Conversational',
] as const

export type VoiceCategory = typeof VOICE_CATEGORIES[number]

